def get_unique_id():
    """
    Returns a unique ID for this process.
    """
    return uuid.uuid4()


def get_unique_name(prefix=''):
    """
    Returns a unique name for this process.
    """
    return '%s_%s' % (prefix, get_unique_id())


def get_unique_path(prefix=''):
